create table patient_medical_record
(
    record_uuid      varchar(36)                                                not null
        primary key,
    patient_uuid     varchar(36)                                                not null,
    patient_name     varchar(20)                                                null comment '患者名',
    doctor_number    int                                                        null comment '医生编号',
    doctor_name      varchar(20)                                                null comment '医生名',
    diagnosis        varchar(255) default '患者在本院完成注册，并且开始病例管理' null,
    treatment        varchar(255) default '治疗方案记录开始...'                 null,
    diagnosis_pic    varchar(255)                                               null comment '实际诊断图片',
    create_time      datetime     default CURRENT_TIMESTAMP                     null,
    update_time      datetime     default CURRENT_TIMESTAMP                     null on update CURRENT_TIMESTAMP,
    institution      varchar(50)                                                null comment '机构',
    institution_uuid varchar(36)                                                null,
    constraint patient_medical_record_ibfk_1
        foreign key (patient_uuid) references patient (uuid)
            on delete cascade
);

create index patient_uuid
    on patient_medical_record (patient_uuid);

